section.artwork:
>> Request <<

GET /servlet/timezone/capabilities HTTP/1.1
Host: tz.example.com

>> Response <<

HTTP/1.1 200 OK
Date: Wed, 4 Jun 2008 09:32:12 GMT
Content-Type: application/json; charset="utf-8"
Content-Length: xxxx

{
  "version": 1,

  "info": {
    "primary-source": "Olson:2011m",
    "formats": [
      "text/calendar",
      "application/calendar+xml",
      "application/calendar+json"
    ],
    "truncated" : {
      "any": false,
      "ranges": [
        {
          "start": "1970-01-01T00:00:00Z",
          "end": "*"
        },
        {
          "start":"2010-01-01T00:00:00Z",
          "end":"2020-01-01T00:00:00Z"
        }
      ],
      "untruncated": true
    },
    "provider-details": "http://tz.example.com/about.html",
    "contacts": ["mailto:tzs@example.org"]
  },
  "actions": [
    {
      "name": "capabilities",
      "uri-template": "/servlet/timezone/capabilities",
      "parameters": []
    },

    {
      "name": "list",
      "uri-template": "/servlet/timezone/zones{?changedsince}",
      "parameters": [
        {
          "name": "changedsince",
          "required": false,
          "multi": false
        }
      ]
    },

    {
      "name": "get",
      "uri-template": "/servlet/timezone/zones{/tzid}{?start,end}",
      "parameters": [
        {
          "name": "start",
          "required": false,
          "multi": false
        },
        {
          "name": "end",
          "required": false,
          "multi": false
        }
      ]
    },

    {
      "name": "expand",
      "uri-template":
        "/servlet/timezone/zones{/tzid}/observances{?start,end}",
      "parameters": [
        {
          "name": "start",
          "required": true,
          "multi": false
        },
        {
          "name": "end",
          "required": true,
          "multi": false
        }
      ]
    },

    {
      "name": "find",
      "uri-template": "/servlet/timezone/zones{?pattern}",
      "parameters": [
        {
          "name": "pattern",
          "required": true,
          "multi": false
        }
      ]
    },

    {
      "name": "leapseconds",
      "uri-template": "/servlet/timezone/leapseconds",
      "parameters": []
    }
  ]
}

>> Request <<

GET /servlet/timezone/zones?pattern=US/Eastern HTTP/1.1
Host: tz.example.com

>> Response <<

HTTP/1.1 200 OK
Date: Wed, 4 Jun 2008 09:32:12 GMT
Content-Type: application/json; charset="utf-8"
Content-Length: xxxx

{
  "synctoken": "2009-10-11T09:32:11Z",
  "timezones": [
    {
      "tzid": "America/New_York",
      "etag": "123456789-000-111",
      "last-modified": "2009-09-17T01:39:34Z",
      "publisher": "Example.com",
      "version": "2015a",
      "aliases":["US/Eastern"],
      "local-names": [
        {
          "name": "America/New_York",
          "lang": "en_US"
        }
      ]
    },
    {
      "tzid": "America/Detroit",
      "etag": "123456789-999-222",
      "last-modified": "2009-09-17T01:39:34Z",
      "publisher": "Example.com",
      "version": "2015a",
      "aliases":["US/Eastern"],
      "local-names": [
        {
          "name": "America/Detroit",
          "lang": "en_US"
        }
      ]
    },
    ...
  ]
}

>> Request <<

GET /servlet/timezone/leapseconds HTTP/1.1
Host: tz.example.com

>> Response <<

HTTP/1.1 200 OK
Date: Wed, 4 Jun 2008 09:32:12 GMT
Content-Type: application/json; charset="utf-8"
Content-Length: xxxx

{
  "expires": "2015-12-28",
  "publisher": "Example.com",
  "version": "2015d",
  "leapseconds": [
    {
      "utc-offset": 10,
      "onset": "1972-01-01",
    },
    {
      "utc-offset": 11,
      "onset": "1972-07-01",
    },
    ...
    {
      "utc-offset": 35,
      "onset": "2012-07-01",
    },
    {
      "utc-offset": 36,
      "onset": "2015-07-01",
    }
  ]
}
